package ai.eva.android.probe;
import android.app.*;import android.content.*;import android.os.*;import java.io.*;import java.net.*;import java.util.*;
/** Loopback-only receiver for PCAPdroid's documented UDP-export API. */
public class NetworkCaptureService extends Service {
 final android.os.Handler timer=new android.os.Handler(android.os.Looper.getMainLooper());boolean receiverStarted,limitReached;
 static volatile NetworkCaptureService live;static volatile DatagramSocket prepared;static volatile File file;static volatile String state="未开始",scope="";static volatile long bytes;static volatile int datagrams;static volatile boolean active;
 static synchronized int prepare(Context c,String filter)throws Exception{if(active||prepared!=null||live!=null)throw new IOException("已有采集进行中，请先停止");File dir=WorkspaceFiles.resolve(c,"network-captures");dir.mkdirs();file=new File(dir,"capture-"+System.currentTimeMillis()+".pcap");prepared=new DatagramSocket(new InetSocketAddress(InetAddress.getByName("127.0.0.1"),0));prepared.setSoTimeout(1000);scope=filter;bytes=0;datagrams=0;state="等待采集授权";active=true;return prepared.getLocalPort();}
 static void stop(Context c){active=false;DatagramSocket socket=prepared;if(socket!=null)socket.close();prepared=null;c.stopService(new Intent(c,NetworkCaptureService.class));if(!state.startsWith("失败")&&!state.startsWith("已达"))state=bytes>0?"采集已停止":"没有收到数据";}
 public void onCreate(){super.onCreate();live=this;NotificationManager n=getSystemService(NotificationManager.class);n.createNotificationChannel(new NotificationChannel("eva-capture","网络采集",NotificationManager.IMPORTANCE_LOW));PendingIntent open=PendingIntent.getActivity(this,73,new Intent(this,NetworkCaptureActivity.class),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);startForeground(2073,new Notification.Builder(this,"eva-capture").setSmallIcon(android.R.drawable.stat_sys_download).setContentTitle("Eva 网络采集").setContentText("点击查看状态与停止采集").setContentIntent(open).setOngoing(true).setVisibility(Notification.VISIBILITY_SECRET).build());}
 public int onStartCommand(Intent i,int flags,int id){if(receiverStarted)return START_NOT_STICKY;receiverStarted=true;final DatagramSocket socket=prepared;if(socket==null){stopSelf();return START_NOT_STICKY;}try{int duration=NetworkCaptureSession.read(this).optInt("durationSeconds",120);timer.postDelayed(()->stopEngine(),duration*1000L);}catch(Exception ignored){}new Thread(()->{try(FileOutputStream out=new FileOutputStream(file)){byte[] b=new byte[65535];long last=System.currentTimeMillis();while(active&&!socket.isClosed()){DatagramPacket p=new DatagramPacket(b,b.length);try{socket.receive(p);}catch(SocketTimeoutException e){continue;}if(!p.getAddress().isLoopbackAddress())continue;if(bytes+p.getLength()>20L*1024*1024){state="已达 20 MB 上限，正在自动停止采集引擎";if(!limitReached){limitReached=true;stopEngine();}continue;}out.write(p.getData(),p.getOffset(),p.getLength());bytes+=p.getLength();datagrams++;state="正在采集";if(System.currentTimeMillis()-last>1000){out.flush();last=System.currentTimeMillis();}}}catch(Exception e){if(active)state="失败："+e.getMessage();}finally{active=false;socket.close();prepared=null;stopSelf();}},"eva-pcap-receiver").start();return START_NOT_STICKY;}
 void stopEngine(){
  if(live!=this||!active)return;
  if(NetworkCaptureSession.pending!=null){timer.postDelayed(this::stopEngine,1000);return;}
  NetworkCaptureSession.work.execute(()->{try{NetworkCaptureSession.request(this,"stop",new org.json.JSONObject(),null);}catch(Exception error){state="需要停止引擎："+error.getMessage();}});
 }
 public IBinder onBind(Intent i){return null;}public void onDestroy(){timer.removeCallbacksAndMessages(null);active=false;DatagramSocket socket=prepared;if(socket!=null)socket.close();prepared=null;live=null;super.onDestroy();}
}
